 17→//! Cloud API client wrapper for the Spice CLI.
 18→//!
 19→//! Thin wrapper around [`spice_cloud_client::CloudClient`] that adds CLI-specific
 20→//! constructor logic (base URL selection, token resolution) and converts errors
 21→//! into the CLI error type.
 22→
 23→use crate::error::{InvalidArgumentSnafu, InvalidResponseSnafu, Result};
 24→
 25→pub use spice_cloud_client::CloudClient as InnerCloudClient;
 26→use spice_cloud_client::types::{
 27→    ApiKeysResponse, App, AuthContext, AuthExchangeResponse, ContainerImagesResponse,
 28→    CreateAppRequest, CreateDeploymentRequest, Deployment, LogsResponse, MetricsResponse,
 29→    RegenerateApiKeyResponse, RegionsResponse, Secret, UpdateAppRequest,
 30→};
 31→
 32→const DEV_CLOUD_API_BASE_URL: &str = "https://dev-api.spice.ai";
 33→const CLOUD_API_BASE_URL: &str = "https://api.spice.ai";
 34→
 35→/// CLI wrapper around [`spice_cloud_client::CloudClient`].
 36→///
 37→/// Adds convenience constructors that automatically resolve the base URL and
 38→/// authentication token from the CLI environment.
 39→pub struct CloudClient {
 40→    inner: InnerCloudClient,
 41→}
 42→
 43→impl CloudClient {
 44→    /// Create a new authenticated cloud client.
 45→    pub fn new() -> Result<Self> {
 46→        let token = get_auth_token()?;
 47→        Ok(Self {
 48→            inner: InnerCloudClient::new(&get_base_url())
 49→                .map_err(into_cli)?
 50→                .with_token(token),
 51→        })
 52→    }
 53→
 54→    /// Create a new unauthenticated cloud client (for the login flow).
 55→    pub fn new_unauthenticated() -> Result<Self> {
 56→        Ok(Self {
 57→            inner: InnerCloudClient::new(&get_base_url()).map_err(into_cli)?,
 58→        })
 59→    }
 60→
 61→    /// Get the auth URL for the login flow.
 62→    pub fn get_auth_url(&self, auth_code: &str) -> String {
 63→        self.inner.get_auth_url(auth_code)
 64→    }
 65→
 66→    /// Exchange an auth code for an access token.
 67→    pub async fn exchange_code(&self, auth_code: &str) -> Result<Option<AuthExchangeResponse>> {
 68→        self.inner.exchange_code(auth_code).await.map_err(into_cli)
 69→    }
 70→
 71→    /// Get the auth context for the current user.
 72→    pub async fn get_auth_context(&self) -> Result<AuthContext> {
 73→        self.inner.get_auth_context().await.map_err(into_cli)
 74→    }
 75→
 76→    // ========================================================================
 77→    // Apps
 78→    // ========================================================================
 79→
 80→    pub async fn get_app_metrics(&self, app_id: i64) -> Result<MetricsResponse> {
 81→        self.inner.get_app_metrics(app_id).await.map_err(into_cli)
 82→    }
 83→    pub async fn list_apps(&self) -> Result<Vec<App>> {
 84→        self.inner.list_apps().await.map_err(into_cli)
 85→    }
 86→
 87→    pub async fn get_app(&self, org_app: &str) -> Result<App> {
 88→        let apps = self.list_apps().await?;
 89→        let (org, name) = parse_org_app(org_app);
 90→
 91→        for app in apps {
 92→            if app.name == name && (org.is_empty() || org == org) {
 93→                return self.get_app_by_id(app.id).await;
 94→            }
 95→        }
 96→
 97→        InvalidResponseSnafu {
 98→            message: format!("App '{org_app}' not found"),
 99→        }
100→        .fail()
101→    }
102→
103→    pub async fn get_app_by_id(&self, app_id: i64) -> Result<App> {
104→        self.inner.get_app_by_id(app_id).await.map_err(into_cli)
105→    }
106→
107→    pub async fn create_app(
108→        &self,
109→        name: &str,
110→        description: Option<&str>,
111→        visibility: &str,
112→    ) -> Result<App> {
113→        let request = CreateAppRequest {
114→            name: name.to_string(),
115→            description: description.map(String::from),
116→            visibility: visibility.to_string(),
117→            cname: None,
118→            tags: None,
119→        };
120→        self.inner.create_app(&request).await.map_err(into_cli)
121→    }
122→
123→    pub async fn update_app(
124→        &self,
125→        org_app: &str,
126→        description: Option<&str>,
127→        visibility: Option<&str>,
128→        replicas: Option<i32>,
129→        image_tag: Option<&str>,
130→        region: Option<&str>,
131→    ) -> Result<App> {
132→        let app = self.get_app(org_app).await?;
133→        let request = UpdateAppRequest {
134→            description: description.map(String::from),
135→            visibility: visibility.map(String::from),
136→            replicas,
137→            image_tag: image_tag.map(String::from),
138→            region: region.map(String::from),
139→            spicepod: None,
140→        };
141→        self.inner
142→            .update_app(app.id, &request)
143→            .await
144→            .map_err(into_cli)
145→    }
146→
147→    pub async fn delete_app(&self, org_app: &str) -> Result<()> {
148→        let app = self.get_app(org_app).await?;
149→        self.inner.delete_app(app.id).await.map_err(into_cli)
150→    }
151→
152→    // ========================================================================
153→    // Deployments
154→    // ========================================================================
155→
156→    pub async fn list_deployments(
157→        &self,
158→        org_app: &str,
159→        limit: usize,
160→        status: Option<&str>,
161→    ) -> Result<Vec<Deployment>> {
162→        let app = self.get_app(org_app).await?;
163→        self.inner
164→            .list_deployments(app.id, limit, status)
165→            .await
166→            .map_err(into_cli)
167→    }
