169→    pub async fn get_latest_deployment(&self, org_app: &str) -> Result<Deployment> {
170→        let deployments = self.list_deployments(org_app, 1, None).await?;
171→        deployments
172→            .into_iter()
173→            .next()
174→            .ok_or_else(|| crate::error::Error::InvalidResponse {
175→                message: format!("No deployments found for '{org_app}'"),
176→            })
177→    }
178→
179→    pub async fn create_deployment(
180→        &self,
181→        org_app: &str,
182→        image_tag: Option<&str>,
183→        replicas: Option<i32>,
184→        debug: bool,
185→    ) -> Result<Deployment> {
186→        let app = self.get_app(org_app).await?;
187→        let request = CreateDeploymentRequest {
188→            image: None,
189→            image_tag: image_tag.map(String::from),
190→            replicas,
191→            branch: None,
192→            commit_sha: None,
193→            commit_message: None,
194→            channel: None,
195→            debug,
196→        };
197→        self.inner
198→            .create_deployment(app.id, &request)
199→            .await
200→            .map_err(into_cli)
201→    }
202→
203→    pub async fn get_deployment_logs(
