 30→
 31→/// State for an active benchmark run provisioned via `setup`.
 32→struct RunState {
 33→    /// Spice Cloud app ID.
 34→    app_id: i64,
 35→    /// API key for the app (used for Flight SQL authentication).
 36→    api_key: String,
 37→    /// Flight SQL endpoint URL derived from the cname.
 38→    flight_url: String,
 39→    /// Cloud client used during provisioning (reused for teardown).
 40→    cloud: CloudClient,
 41→    /// Region cname (used to build the SQL endpoint URL).
 42→    cname: String,
 43→    /// Table names created for this run (for cleanup during teardown).
 44→    created_tables: Vec<String>,
 45→}
 46→
 47→/// System adapter handler that provisions Spice Cloud apps.
 48→struct SpidapterHandler {
 49→    /// Active runs keyed by run ID.
 50→    runs: HashMap<Uuid, RunState>,
 51→    /// Spice Cloud API URL override (from CLI args).
 52→    api_url_override: Option<String>,
 53→    /// Timeout in seconds for deployment readiness.
 54→    ready_wait: u64,
 55→    /// Release channel for the spice.ai runtime image.
 56→    channel: Option<String>,
 57→}
 58→
 59→impl SpidapterHandler {
 60→    fn new(args: &StdioArgs) -> Self {
 61→        Self {
 62→            runs: HashMap::new(),
 63→            api_url_override: args.spice_cloud_api_url.clone(),
 64→            ready_wait: args.ready_wait,
 65→            channel: args.channel.clone(),
 66→        }
 67→    }
 68→}
 69→
 70→#[async_trait]
 71→impl Handler for SpidapterHandler {
 72→    async fn setup(
 73→        &mut self,
 74→        run_id: Uuid,
 75→        metadata: HashMap<String, serde_json::Value>,
 76→    ) -> Result<SetupResponse, String> {
 77→        eprintln!(
 78→            "[stdio] setup: run_id={run_id}, metadata_keys={:?}",
 79→            metadata.keys().collect::<Vec<_>>()
 80→        );
 81→
 82→        let state = provision_spice_cloud_app(
 83→            run_id,
 84→            self.api_url_override.as_deref(),
 85→            self.ready_wait,
 86→            self.channel.as_deref(),
 87→        )
 88→        .await
 89→        .map_err(|e| format!("Setup failed: {e}"))?;
 90→
 91→        let response = SetupResponse {
 92→            driver: AdbcDriver::Flightsql,
 93→            db_kwargs: HashMap::from([
 94→                (
 95→                    "uri".to_string(),
 96→                    serde_json::Value::String(state.flight_url.clone()),
 97→                ),
 98→                (
 99→                    "username".to_string(),
100→                    serde_json::Value::String(String::new()),
101→                ),
102→                (
103→                    "password".to_string(),
104→                    serde_json::Value::String(state.api_key.clone()),
105→                ),
106→            ]),
107→        };
108→
109→        self.runs.insert(run_id, state);
110→        Ok(response)
111→    }
112→
113→    async fn metrics(&mut self, run_id: Uuid) -> std::result::Result<MetricsResponse, String> {
114→        let state = self
115→            .runs
116→            .get(&run_id)
117→            .ok_or_else(|| format!("No active run found for {run_id}"))?;
118→
119→        let cloud_metrics = state
120→            .cloud
121→            .get_app_metrics(state.app_id)
122→            .await
123→            .map_err(|e| format!("Failed to fetch metrics: {e}"))?;
124→
125→        let pods = cloud_metrics.metrics.values().collect::<Vec<_>>();
126→
127→        let resource = if pods.is_empty() {
128→            ResourceMetrics::default()
129→        } else {
130→            let avg_cpu = pods.iter().filter_map(|p| p.cpu_usage_percent).sum::<f64>()
131→                / pods
132→                    .iter()
133→                    .filter_map(|p| p.cpu_usage_percent.is_some().then(|| 1.0))
134→                    .sum::<f64>();
135→            let total_memory = pods
136→                .iter()
137→                .filter_map(|p| p.memory_usage_bytes)
138→                .sum::<u64>()
139→                / pods
140→                    .iter()
141→                    .filter_map(|p| p.cpu_usage_percent.is_some().then(|| 1))
142→                    .sum::<u64>();
143→
144→            ResourceMetrics {
145→                cpu_usage_percent: Some(avg_cpu),
146→                memory_usage_bytes: Some(total_memory as u64),
147→                disk_read_bytes: None,
148→                disk_write_bytes: None,
149→                disk_read_iops: None,
150→                disk_write_iops: None,
151→            }
152→        };
153→
154→        Ok(MetricsResponse {
155→            resource,
156→            ingestion: IngestionMetrics::default(),
157→        })
158→    }
159→
160→    async fn create_tables(
161→        &mut self,
162→        run_id: Uuid,
163→        datasets: HashMap<String, DatasetConfig>,
164→    ) -> Result<CreateTablesResponse, String> {
165→        eprintln!("[stdio] create_tables: run_id={run_id}");
166→
167→        let state = self
168→            .runs
169→            .get_mut(&run_id)
170→            .ok_or_else(|| format!("Unknown run_id: {run_id}"))?;
171→
172→        let client = reqwest::Client::builder()
173→            .timeout(Duration::from_secs(60))
174→            .build()
175→            .map_err(|e| format!("Failed to create HTTP client: {e}"))?;
176→
177→        let sql_url = sql_url_from_cname(&state.cname);
178→
179→        for (table_name, config) in &datasets {
180→            let ddl = create_table_ddl(table_name, config);
181→            eprintln!("[stdio] create_tables: executing DDL: {ddl}");
182→
183→            let response = client
184→                .post(&sql_url)
185→                .header("X-API-Key", &state.api_key)
186→                .body(ddl.clone())
187→                .send()
188→                .await
189→                .map_err(|e| format!("Failed to send DDL for table '{table_name}': {e}"))?;
190→
191→            if !response.status().is_success() {
192→                let status = response.status();
193→                let body = response
194→                    .text()
195→                    .await
196→                    .unwrap_or_else(|_| "<failed to read body>".to_string());
197→                return Err(format!(
198→                    "DDL for table '{table_name}' failed ({status}): {body}"
199→                ));
200→            }
201→
202→            state.created_tables.push(table_name.clone());
203→            eprintln!("[stdio] create_tables: table '{table_name}' created");
204→        }
205→        Ok(CreateTablesResponse { ok: true })
206→    }
207→
208→    async fn teardown(&mut self, run_id: Uuid) -> Result<TeardownResponse, String> {
209→        eprintln!("[stdio] teardown: run_id={run_id}");
210→
211→        let Some(state) = self.runs.remove(&run_id) else {
212→            eprintln!("[stdio] teardown: run_id={run_id} not found (already torn down?)");
213→            return Ok(TeardownResponse { ok: true });
214→        };
215→
216→        // Drop tables via DDL before deleting the app
217→        if !state.created_tables.is_empty() {
218→            let client = reqwest::Client::builder()
219→                .timeout(Duration::from_secs(30))
220→                .build()
221→                .map_err(|e| format!("Failed to create HTTP client: {e}"))?;
222→
223→            let sql_url = sql_url_from_cname(&state.cname);
224→
225→            for table_name in &state.created_tables {
226→                let ddl = format!("DROP TABLE IF EXISTS {}", quote_ident(table_name));
227→                eprintln!("[stdio] teardown: executing DDL: {ddl}");
228→
229→                match client
230→                    .post(&sql_url)
231→                    .header("X-API-Key", &state.api_key)
232→                    .body(ddl)
233→                    .send()
234→                    .await
235→                {
236→                    Ok(response) if response.status().is_success() => {
237→                        eprintln!("[stdio] teardown: table '{table_name}' dropped");
238→                    }
239→                    Ok(response) => {
240→                        let status = response.status();
241→                        let body = response
242→                            .text()
243→                            .await
244→                            .unwrap_or_else(|_| "<failed to read body>".to_string());
245→                        eprintln!(
246→                            "[stdio] teardown: failed to drop table '{table_name}' ({status}): {body}"
247→                        );
248→                    }
249→                    Err(e) => {
250→                        eprintln!("[stdio] teardown: failed to drop table '{table_name}': {e}");
251→                    }
252→                }
253→            }
254→        }
255→
256→        eprintln!(
257→            "[stdio] teardown: deleting app {} at {}",
258→            state.app_id,
259→            state.cloud.base_url()
260→        );
261→
262→        commands::delete_app(&state.cloud, state.app_id)
263→            .await
264→            .map_err(|e| format!("Failed to delete app {}: {e}", state.app_id))?;
265→
266→        eprintln!("[stdio] teardown: app {} deleted", state.app_id);
267→        Ok(TeardownResponse { ok: true })
268→    }
269→}
270→
271→pub async fn run_stdio_server(args: &StdioArgs) -> anyhow::Result<()> {
272→    let handler = SpidapterHandler::new(args);
273→    let mut server = Server::new(handler);
274→    server
275→        .run_stdio()
276→        .await
277→        .map_err(|e| anyhow::anyhow!("Stdio server error: {e}"))
278→}
279→
280→// ── Spice Cloud provisioning ─────────────────────────────────────────
281→
282→/// Provision a Spice Cloud app from the setup request.
283→///
284→/// Follows the same flow as `SpiceCloudSpicedStarter::start()`:
285→/// 1. Resolve the default cname / region
286→/// 2. Create or find the SCP app
287→/// 3. Generate and upload the spicepod from the dataset configs
288→/// 4. Set secrets (RUNNER + any env-based secrets)
289→/// 5. Create a deployment
290→/// 6. Wait for the deployment to become ready
291→async fn provision_spice_cloud_app(
292→    run_id: Uuid,
293→    api_url_override: Option<&str>,
294→    ready_wait: u64,
295→    channel: Option<&str>,
296→) -> anyhow::Result<RunState> {
297→    let cloud = commands::build_cloud_client(api_url_override)?;
298→
299→    let cname = commands::resolve_default_cname(&cloud).await?;
300→    let flight_url = commands::flight_url_from_cname(&cname);
301→    let run_id_str = run_id.to_string();
302→    let short_id = run_id_str.split('-').next().unwrap_or_default();
303→    let app_name = commands::sanitize_app_name(&format!("spidapter-{short_id}"));
304→
305→    eprintln!("[stdio] Spice Cloud API: {}", cloud.base_url());
306→    eprintln!("[stdio] Region cname: {cname}");
307→    eprintln!("[stdio] Flight endpoint: {flight_url}");
308→    eprintln!("[stdio] App name: {app_name}");
309→
310→    let (app_id, app_api_key) = commands::ensure_spice_cloud_app(&cloud, &app_name).await?;
311→
312→    let api_key = app_api_key.ok_or_else(|| {
313→        anyhow::anyhow!("Spice Cloud did not return an API key for app '{app_name}'")
314→    })?;
315→
316→    eprintln!("[stdio] App ID: {app_id}");
317→
318→    // Generate initial spicepod YAML (tables created later via create_tables)
319→    let spicepod_yaml = generate_initial_spicepod(&run_id)?;
320→    eprintln!("[stdio] Generated spicepod:\n{spicepod_yaml}");
321→
322→    eprintln!("[stdio] Uploading spicepod to app...");
323→    commands::apply_spicepod_to_app(&cloud, app_id, &spicepod_yaml).await?;
324→    eprintln!("[stdio] Spicepod uploaded");
325→
326→    // Set secrets from environment for any secret references in the spicepod
327→    eprintln!("[stdio] Setting secrets from spicepod...");
328→    commands::secrets::set_spicepod_secrets(&cloud, app_id, &spicepod_yaml).await?;
329→    eprintln!("[stdio] Spicepod secrets set");
330→
331→    eprintln!("[stdio] Setting RUNNER secret...");
332→    commands::secrets::set_secret(&cloud, app_id, "RUNNER", "spidapter").await?;
333→    eprintln!("[stdio] RUNNER secret set");
334→
335→    eprintln!("[stdio] Creating deployment...");
336→    commands::create_deployment(&cloud, app_id, channel).await?;
337→
338→    let poll_client = reqwest::Client::builder()
339→        .timeout(Duration::from_secs(600))
340→        .build()?;
341→    commands::wait_for_deployment_ready(
342→        &poll_client,
343→        &cname,
344→        &api_key,
345→        Duration::from_secs(ready_wait),
346→    )
347→    .await?;
348→
349→    eprintln!("[stdio] Spice Cloud deployment ready for app '{app_name}' at {flight_url}");
350→
351→    Ok(RunState {
352→        app_id,
353→        api_key,
354→        flight_url,
355→        cloud,
356→        cname,
357→        created_tables: Vec::new(),
358→    })
359→}
360→
361→/// Build the SQL endpoint URL from a Spice Cloud cname.
362→fn sql_url_from_cname(cname: &str) -> String {
363→    format!("https://{cname}.spiceai.io/v1/sql")
364→}
365→
366→/// Generate a `CREATE TABLE IF NOT EXISTS` DDL statement from a dataset's Arrow schema.
367→fn create_table_ddl(table_name: &str, config: &DatasetConfig) -> String {
368→    let columns: Vec<String> = config
369→        .schema
370→        .fields()
371→        .iter()
372→        .map(|f| {
373→            let sql_type = sql_type_for_arrow(f.data_type());
374→            let nullable = if f.is_nullable() { "" } else { " NOT NULL" };
375→            format!("{} {sql_type}{nullable}", quote_ident(f.name()))
376→        })
377→        .collect();
378→
379→    format!(
380→        "CREATE TABLE IF NOT EXISTS {} ({})",
381→        quote_ident(table_name),
382→        columns.join(", ")
383→    )
384→}
385→
386→/// Map Arrow data types to SQL type names for DDL.
387→fn sql_type_for_arrow(data_type: &DataType) -> String {
388→    match data_type {
389→        DataType::Boolean => "BOOLEAN".to_string(),
390→        DataType::Int8 => "TINYINT".to_string(),
391→        DataType::UInt8 | DataType::Int16 => "SMALLINT".to_string(),
392→        DataType::UInt16 | DataType::Int32 => "INT".to_string(),
393→        DataType::UInt32 | DataType::Int64 => "BIGINT".to_string(),
394→        DataType::UInt64 => "DECIMAL(20, 0)".to_string(),
395→        DataType::Float32 => "FLOAT".to_string(),
396→        DataType::Float64 => "DOUBLE".to_string(),
397→        DataType::Date32 | DataType::Date64 => "DATE".to_string(),
398→        DataType::Timestamp(
399→            TimeUnit::Second | TimeUnit::Millisecond | TimeUnit::Microsecond | TimeUnit::Nanosecond,
400→            _,
401→        ) => "TIMESTAMP".to_string(),
402→        DataType::Decimal128(p, s) => format!("DECIMAL({p}, {s})"),
403→        DataType::Binary | DataType::LargeBinary => "BINARY".to_string(),
404→        _ => "VARCHAR".to_string(),
405→    }
406→}
407→
408→fn quote_ident(ident: &str) -> String {
409→    format!("\"{}\"", ident.replace('"', "\"\""))
410→}
411→
412→/// Generate the initial spicepod YAML with an Iceberg Glue catalog as the default catalog.
413→fn generate_initial_spicepod(run_id: &Uuid) -> anyhow::Result<String> {
414→    let run_id_str = run_id.to_string();
415→    let short_id = run_id_str.split('-').next().unwrap_or_default();
416→    let region = std::env::var("SPIDAPTER_ICEBERG_REGION")
417→        .or_else(|_| std::env::var("AWS_REGION"))
418→        .or_else(|_| std::env::var("AWS_DEFAULT_REGION"))
419→        .unwrap_or_else(|_| "us-east-1".to_string());
420→    let catalog_from = if let Ok(from) = std::env::var("SPIDAPTER_ICEBERG_CATALOG_FROM") {
421→        from
422→    } else {
423→        let account_id = std::env::var("SPIDAPTER_ICEBERG_CATALOG_ACCOUNT_ID")
424→            .or_else(|_| std::env::var("AWS_ICEBERG_ACCOUNT_ID"))
425→            .map_err(|_| {
426→                anyhow::anyhow!(
427→                    "Missing Iceberg catalog account id. Set SPIDAPTER_ICEBERG_CATALOG_FROM or SPIDAPTER_ICEBERG_CATALOG_ACCOUNT_ID (or AWS_ICEBERG_ACCOUNT_ID)."
428→                )
429→            })?;
430→
431→        format!(
432→            "iceberg:https://glue.{region}.amazonaws.com/iceberg/v1/catalogs/{account_id}/namespaces"
433→        )
434→    };
435→
436→    Ok(format!(
437→        "version: v1beta1
438→kind: Spicepod
439→name: spidapter-{short_id}
440→
441→catalogs:
442→  - from: {catalog_from}
443→    name: spice
444→    access: read_write_create
445→    params:
446→      iceberg_sigv4_enabled: true
447→      iceberg_s3_access_key_id: ${{secrets:AWS_ACCESS_KEY_ID}}
448→      iceberg_s3_secret_access_key: ${{secrets:AWS_SECRET_ACCESS_KEY}}
449→      iceberg_s3_region: {region}
450→"
451→    ))
452→}
